def photo(code,alt):
 r=manifest[code]
 return {'src':r['displayPath'],'alt':alt,'generated':True,'presentation':'editorial','originalSrc':r['referencePath']}
def product(r):
 code=r['supplierCode'];name,tag,desc,details=copy[code]
 brand='Sanicat' if name.startswith('Sanicat') else 'Moderna' if name.startswith('Moderna') else 'EBI' if name.startswith('EBI') else 'Duvo+'
 cat={'Лотки':'Наполнитель','Лопатки':'Наполнитель','Когтеточки':'Аксессуары','Миски':'Миски и поилки','Поилки':'Миски и поилки'}.get(r['category'],r['category'])
 p={'id':'yagu-'+code,'name':name,'brand':brand,'category':cat,'pet':'cat','isReal':True,'isNew':True,'price':None,'priceStatus':'pending','purchasePrice':None,'purchasePriceStatus':'pending','availabilityStatus':'pending','tag':tag,'line':brand+' · '+r['packOrDimensions'],'weight':r['packOrDimensions'],'sizes':[r['packOrDimensions']],'optionLabel':'Вариант','label':r['packOrDimensions'],'description':desc,'details':details,'image':photo(code,name),'supplier':{'name':'Yagu','sku':code,'url':r['sourceUrl']},'productSource':{'name':'Yagu - каталог 2026','url':r['sourceUrl'],'kind':'supplier'},'imageSource':{'name':'Yagu - каталог 2026','pageUrl':r['sourceUrl']}}
 if code=='7502810':p['imageSource']={'name':'Duvo Tower - точная коричневая модель','pageUrl':'https://www.paraperrosygatos.es/collections/rascadores/products/rascador-gato-tower-marron-36-x-35-x-70-cm'}
 if cat=='Игрушки':p['details']+=['Играйте под присмотром, убирайте повреждённые игрушки']
 variant={**p,'id':p['id']+'-catalog-pack'}
 return {**p,'defaultVariantId':variant['id'],'variants':[variant]}
products=[product(r) for r in source if r['supplierCode'] not in ['T68669','T68670']]
assert len(products)==24
malt=[]
for r in source:
 if r['supplierCode'] not in ['T68669','T68670']:continue
 p={'id':'tc-84ace3f3f7-yagu-'+r['supplierCode'],'name':'GimCat Malt-Soft Extra','brand':'GimCat','category':'Уход','pet':'cat','isReal':True,'isNew':True,'price':None,'priceStatus':'pending','purchasePrice':None,'purchasePriceStatus':'pending','availabilityStatus':'pending','label':r['packOrDimensions'],'weight':r['packOrDimensions'],'sizes':[r['packOrDimensions']],'optionLabel':'Упаковка','tag':'Мальт-паста','line':'GimCat · '+r['packOrDimensions'],'description':'Мальт-паста GimCat Malt-Soft Extra для кошек Фасовка '+r['packOrDimensions'],'details':['Мальт-паста для кошек','Упаковка '+r['packOrDimensions'],'Используйте по инструкции производителя на упаковке'],'packageWeightKg':int(r['packOrDimensions'].split()[0])/1000,'image':photo('T68669','GimCat Malt-Soft Extra - изображение линейки'),'supplier':{'name':'Yagu','sku':r['supplierCode'],'url':r['sourceUrl']},'productSource':{'name':'Yagu - каталог 2026','url':r['sourceUrl'],'kind':'supplier'},'imageSource':{'name':'Yagu - каталог 2026','pageUrl':r['sourceUrl']}}
 malt.append(p)
output='// Selected Yagu catalogue items - retail and purchase prices pending\nexport const yaguProducts = '+json.dumps(products,ensure_ascii=False,indent=2)+';\nconst yaguMaltVariants = '+json.dumps(malt,ensure_ascii=False,indent=2)+''';
// Extend the existing Malt-Soft Extra family without adding a duplicate catalogue card
export function expandYaguCare(products) {
  return products.map(product => {
    if (product.id !== 'tc-84ace3f3f7') return product;
    const variants = [...product.variants, ...yaguMaltVariants].sort((a, b) => a.packageWeightKg - b.packageWeightKg);
    return { ...product, variants, sizes: variants.map(variant => variant.label) };
  });
}
'''
(ROOT/'yagu-products.js').write_text(output)
print('24 new cards and 2 Malt-Soft Extra pack variants prepared')
